        for r in (0, R-1):
            if grid[r][c] != 5 and not seen[r][c]:
                seen[r][c] = True; q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and grid[nr][nc] != 5:
                seen[nr][nc] = True; q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 5 and not seen[r][c]:
                out[r][c] = 4
    return out
